""";

    public async Task SeedAsync(CancellationToken ct = default)
    {
        // Extract ONLY digit tokens. If anything else exists besides separators, fail.
        // Allowed separators: whitespace, commas.
        var invalid = Regex.Replace(RawAdminIds, @"[\d\s,]+", "");
        if (!string.IsNullOrEmpty(invalid))
            throw new InvalidOperationException($"AdmissionsSeeder: invalid characters found in seed list: '{invalid}'");

        var ids = Regex.Matches(RawAdminIds, @"\d+")
            .Select(m => m.Value)
            .ToList();

        if (ids.Count == 0)
            throw new InvalidOperationException("AdmissionsSeeder: seed list is empty after parsing.");

        // In-memory dedupe (DB unique index is still the final guard)
        var distinct = ids.Distinct(StringComparer.Ordinal).ToList();

        // Query existing
        var existing = await _db.AdmissionsNumbers
            .AsNoTracking()
            .Where(x => distinct.Contains(x.AdminId))
            .Select(x => x.AdminId)
            .ToListAsync(ct);

        var existingSet = existing.ToHashSet(StringComparer.Ordinal);

        var toInsert = distinct
            .Where(x => !existingSet.Contains(x))
            .Select(x => new AdmissionsNumber { AdminId = x })
            .ToList();

        if (toInsert.Count == 0)
        {
            _logger.LogInformation("AdmissionsSeeder: all {Count} admissions already exist.", distinct.Count);
            return;
        }

        await _db.AdmissionsNumbers.AddRangeAsync(toInsert, ct);
        await _db.SaveChangesAsync(ct);

        _logger.LogInformation(
            "AdmissionsSeeder: inserted {Inserted}. Total in seed list={Total}, duplicates in list={Dupes}.",
            toInsert.Count,
            ids.Count,
            ids.Count - distinct.Count);
    }
}